hands_on.solution:
#include <iostream>
using namespace std;

void orderPair(int& lo, int& hi) {
    if (lo > hi) {
        int t = lo;
        lo = hi;
        hi = t;
    }
}

int main() {
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        int a, b;
        cin >> a >> b;
        orderPair(a, b);
        cout << a << " " << b << "\n";
    }
    return 0;
}
